import { test, expect } from '@playwright/test';

test.describe('Error Toast Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display error toast when action fails', async ({ page }) => {
    // Click button that triggers a failing action
    await page.getByRole('button', { name: /trigger error/i }).click();

    // Wait for and verify error toast appears
    const errorToast = page.getByRole('alert');
    await expect(errorToast).toBeVisible();

    // Verify error message content
    await expect(errorToast).toContainText(/error|failed/i);
  });

  test('should display error toast with correct message text', async ({ page }) => {
    // Click button that triggers a specific error
    await page.getByRole('button', { name: /submit form/i }).click();

    // Verify error toast is visible with specific message
    const errorToast = page.getByRole('alert');
    await expect(errorToast).toBeVisible();
    await expect(errorToast).toContainText('Something went wrong');
  });

  test('should dismiss error toast when close button is clicked', async ({ page }) => {
    // Trigger error action
    await page.getByRole('button', { name: /trigger error/i }).click();

    // Verify toast is visible
    const errorToast = page.getByRole('alert');
    await expect(errorToast).toBeVisible();

    // Click close button on toast
    await page.getByRole('button', { name: /close|dismiss/i }).click();

    // Verify toast is no longer visible
    await expect(errorToast).not.toBeVisible();
  });

  test('should auto-dismiss error toast after timeout', async ({ page }) => {
    // Trigger error action
    await page.getByRole('button', { name: /trigger error/i }).click();

    // Verify toast is visible
    const errorToast = page.getByRole('alert');
    await expect(errorToast).toBeVisible();

    // Wait for auto-dismiss timeout (typically 5 seconds)
    await expect(errorToast).not.toBeVisible({ timeout: 6000 });
  });
});
